package org.zhixiaoce.aperture;
import android.app.*;import android.content.*;import android.graphics.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import java.lang.reflect.*;import java.util.concurrent.*;import java.util.function.BooleanSupplier;
/** Run LAST in the isolated probe package. Generated fixtures remain on disk; no cleanup/listener. */
public final class Round3PhotosRunner extends Instrumentation {
    final JSONArray checks=new JSONArray();Activity open;
    private Object field(Object target,String name){for(Class<?> c=target.getClass();c!=null;c=c.getSuperclass())try{Field f=c.getDeclaredField(name);f.setAccessible(true);return f.get(target);}catch(NoSuchFieldException ignored){}catch(Exception e){throw new RuntimeException(e);}throw new AssertionError(name);}
    private void check(boolean pass,String label){if(!pass)throw new AssertionError(label);checks.put(label);}
    private void key(int code){ProbeKeys.key(this,open,code);}
    private boolean await(BooleanSupplier condition)throws Exception{CountDownLatch latch=new CountDownLatch(1);boolean[] ok={false};Handler h=new Handler(Looper.getMainLooper());long deadline=SystemClock.uptimeMillis()+4000;h.post(new Runnable(){public void run(){if(condition.getAsBoolean()){ok[0]=true;latch.countDown();}else if(SystemClock.uptimeMillis()>=deadline)latch.countDown();else h.postDelayed(this,20);}});return latch.await(5000,TimeUnit.MILLISECONDS)&&ok[0];}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    @Override public void onStart(){JSONObject result=new JSONObject();try{
        GalleryStore store=new GalleryStore(getTargetContext());check(store.snapshot().getJSONArray("photos").length()==0,"privacy stop: probe package must be empty before synthetic fixture creation");
        for(int color:new int[]{0xff284c56,0xff706044}){Bitmap image=Bitmap.createBitmap(320,180,Bitmap.Config.ARGB_8888);image.eraseColor(color);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();image.compress(Bitmap.CompressFormat.JPEG,90,bytes);image.recycle();store.add(bytes.toByteArray(),()->true);}
        check(store.snapshot().getJSONArray("photos").length()==2,"two generated fixture photos stored without upload");
        R3NativeGalleryProbe a=(R3NativeGalleryProbe)startActivitySync(new Intent(getTargetContext(),R3NativeGalleryProbe.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));open=a;waitForIdleSync();
        check(await(()->a.getWindow().getDecorView().findViewWithTag("native-gallery-picture")!=null&&((ImageView)a.getWindow().getDecorView().findViewWithTag("native-gallery-picture")).getDrawable()!=null),"native viewer decodes existing generated photograph");
        key(20);key(21);check("native-gallery-preview".equals(a.getCurrentFocus().getTag()),"remote reaches native full screen");key(23);NativeGallery gallery=(NativeGallery)field(a,"nativeGallery");check(Boolean.TRUE.equals(field(gallery,"full")),"native full screen opens");key(22);check(Integer.valueOf(1).equals(field(gallery,"index")),"remote Right browses second saved photo");key(23);check(Boolean.TRUE.equals(field(gallery,"paused")),"native OK pauses slideshow");key(4);check(!Boolean.TRUE.equals(field(gallery,"full")),"first Back exits full screen");key(4);check(a.isFinishing(),"second Back exits album");check(store.snapshot().getJSONArray("photos").length()==2,"browsing preserves generated photos");check(a.uploadCreates==0,"native browsing never creates upload session");result.put("ok",true);
    }catch(Throwable e){try{result.put("ok",false).put("error",e.getClass().getSimpleName()+": "+e.getMessage());}catch(JSONException impossible){throw new AssertionError(impossible);}}finally{ProbeReport.finish(this,result,"s96-photos.json",()->{if(open!=null){Activity a=open;runOnMainSync(a::finish);ProbeWait.until(a::isDestroyed,10000,"photo Activity destroyed");}},report->report.put("checks",checks).put("passed",checks.length()).put("syntheticFixturePhotosOnly",true).put("realUploadListenerStarted",false).put("keyReceipts",ProbeKeys.receipts()).put("inputLayer","app-internal-window-dispatch").put("pixelCaptureExecuted",false).put("fixturesRetained",true));}}
}
